from pathlib import Path
import re
paths={}
for p in Path('/home/mbolshov/workspace/review_runtime/static_core/plugins/ets/stdlib').rglob('*.ets'):
    paths.setdefault(p.name,[]).append(p)
mods=[]
for l in Path('/tmp/es2panda_now.log').read_text().splitlines():
 m=re.match(r'^\[(.*?):(\d+):(\d+)\] Warning W0015:', l)
 if m:
  f,ln,col=m.group(1),int(m.group(2)),int(m.group(3))
  for p in paths.get(f,[]):
   lines=p.read_text().splitlines()
   if ln<=len(lines) and ('!' in lines[ln-1] or '?.' in lines[ln-1]): mods.append((p,ln,col)); break
by={}
for p,ln,col in mods: by.setdefault(p,[]).append((ln,col))
for p,ms in by.items():
 text=p.read_text(); lines=text.splitlines(keepends=True)
 for ln,col in sorted(ms, reverse=True):
  raw=lines[ln-1]; nl='\n' if raw.endswith('\n') else ''; s=raw[:-1] if nl else raw; orig=s; idx=col-1
  candidates=[]
  for k in range(max(0,idx-5), min(len(s), idx+100)):
   if s[k]=='!': candidates.append((abs(k-idx),k,'!'))
   if k<len(s)-1 and s[k:k+2]=='?.': candidates.append((abs(k-idx),k,'?.'))
  if candidates:
   _,k,t=min(candidates)
   s=s[:k]+('' if t=='!' else '.')+s[k+(1 if t=='!' else 2):]
  if s!=orig: lines[ln-1]=s+nl
  else: print('nochange',p,ln,col,s)
 if ''.join(lines)!=text:
  p.write_text(''.join(lines)); print('changed',p)
